-- Original approved demo catalog; retain IDs for local bags and favorites.
-- Re-running does not overwrite catalog edits.
begin;
insert into public.boutiques (id,name,ar,mark,line,"lineAr",story,"storyAr")
select * from jsonb_to_recordset($catalog$[{"ar":"نور أتيليه","id":1,"line":"The art of understated abayas.","lineAr":"فن العبايات الراقية بتفاصيل هادئة.","mark":"N","name":"NOOR ATELIER","story":"Designed in Kuwait. Fluid silhouettes, quiet details and fabrics chosen to move with you.","storyAr":"تصاميم كويتية بقصّات انسيابية وتفاصيل هادئة وأقمشة ترافق كل خطوة."},{"ar":"ميزون ديون","id":2,"line":"A softer way to make an entrance.","lineAr":"حضور استثنائي بلمسات ناعمة.","mark":"md","name":"MAISON DUNE","story":"Considered occasionwear in a palette borrowed from the desert. For your most memorable evenings.","storyAr":"أزياء مناسبات مدروسة بألوان مستوحاة من الصحراء، لأمسياتك التي لا تُنسى."},{"ar":"ذا لينن روم","id":3,"line":"Everyday pieces. Exceptional feeling.","lineAr":"قطع يومية بإحساس استثنائي.","mark":"lr","name":"THE LINEN ROOM","story":"Natural textures and relaxed tailoring for unhurried days. Made for the rhythm of Kuwait.","storyAr":"خامات طبيعية وقصّات مريحة لأيام هادئة. مصممة لإيقاع الحياة في الكويت."}]$catalog$::jsonb)
as x(id integer,name text,ar text,mark text,line text,"lineAr" text,story text,"storyAr" text)
on conflict (id) do nothing;
insert into public.products (id,name,ar,brand,price,image,category,sizes,colors,description,"descriptionAr",fresh,best)
select * from jsonb_to_recordset($catalog$[{"ar":"عباية التوقيع","best":true,"brand":1,"category":"abayas","colors":[["Onyx","أسود","#2e2926"],["Sand","رملي","#c9b79e"]],"description":"A study in quiet elegance. A fluid, open-front abaya in premium crepe, finished with delicate champagne piping. Includes a coordinating sheila.","descriptionAr":"أناقة هادئة في عباية مفتوحة من الكريب الفاخر، بلمسات شامبين دقيقة. تشمل شيلة متناسقة.","fresh":true,"id":1,"image":"noor","name":"The Signature Abaya","price":68.5,"sizes":["S","M","L","XL"]},{"ar":"عباية حرير شامبين","best":false,"brand":1,"category":"abayas","colors":[["Champagne","شامبين","#c8b69f"],["Pearl","لؤلؤي","#e6dfd2"]],"description":"Luminous silk, generous sleeves and tonal embroidery. An exquisite drape that catches the afternoon light. Includes a matching sheila.","descriptionAr":"حرير مضيء وأكمام واسعة وتطريز متناغم. انسيابية راقية تتألق تحت ضوء العصر. تشمل شيلة مطابقة.","fresh":true,"id":2,"image":"silk","name":"Champagne Silk Abaya","price":89,"sizes":["S","M","L"]},{"ar":"فستان العاج بثنيات","best":true,"brand":2,"category":"women","colors":[["Ivory","عاجي","#eae2d2"],["Oat","شوفان","#b5a58c"]],"description":"An architectural waist meets soft, sweeping pleats. This fully lined, long-sleeve maxi dress is made for intimate celebrations.","descriptionAr":"خصر منحوت وثنيات ناعمة في فستان ماكسي بأكمام طويلة وبطانة كاملة. مثالي لمناسباتك الحميمة.","fresh":false,"id":3,"image":"dress","name":"The Ivory Pleated Dress","price":76.75,"sizes":["XS","S","M","L"]},{"ar":"طقم الحرير الزيتوني","best":true,"brand":3,"category":"women","colors":[["Olive","زيتوني","#7a7c60"],["Stone","حجري","#b1a696"]],"description":"An effortless pairing of a longline silk tunic and wide-leg trousers. Beautiful together, equally considered apart. Two-piece set.","descriptionAr":"طقم أنيق من تونيك حريري طويل وبنطال واسع. جمال متكامل وقطع مستقلة متعددة الإطلالات.","fresh":true,"id":4,"image":"olive","name":"Olive Silk Co-ord","price":54.25,"sizes":["S","M","L","XL"]},{"ar":"فستان ورد للمناسبات","best":false,"brand":2,"category":"women","colors":[["Rosewater","وردي","#bb9490"],["Clay","طيني","#a98472"]],"description":"A graceful occasion dress with sculptural sleeves and a sweeping hem. Soft rose fabric with a subtle lustre, fully lined.","descriptionAr":"فستان مناسبات راقٍ بأكمام منحوتة وحافة انسيابية. قماش وردي بلمعة خفيفة وبطانة كاملة.","fresh":true,"id":5,"image":"rose","name":"Rosewater Occasion Dress","price":112.5,"sizes":["XS","S","M","L"]},{"ar":"عباية الكاب المنحوت","best":true,"brand":1,"category":"abayas","colors":[["Espresso","إسبريسو","#49392f"],["Onyx","أسود","#292523"]],"description":"A striking cape silhouette with delicate pleats and a beautifully weighted drape. Closed-front design in premium woven crepe.","descriptionAr":"قصّة كاب لافتة بثنيات دقيقة وانسيابية متوازنة. تصميم مغلق من الكريب المنسوج الفاخر.","fresh":false,"id":6,"image":"black","name":"The Sculpted Cape Abaya","price":94.75,"sizes":["S","M","L","XL"]}]$catalog$::jsonb)
as x(id integer,name text,ar text,brand integer,price numeric,image text,category text,sizes text[],colors jsonb,description text,"descriptionAr" text,fresh boolean,best boolean)
on conflict (id) do nothing;
select setval(pg_get_serial_sequence('public.boutiques','id'), (select max(id) from public.boutiques));
select setval(pg_get_serial_sequence('public.products','id'), (select max(id) from public.products));
commit;
